    void advancedConnection(){
        LinearLayout form=col();pad(form,20);form.addView(text("默认使用内置连接。仅在需要连接自己的服务时填写地址；切换连接后需要重新登录。",14,MUTED));gap(form,10);
        EditText endpoint=new EditText(this);endpoint.setSingleLine();endpoint.setInputType(17);endpoint.setHint("留空使用内置连接");endpoint.setText(ApiEndpoint.embedded(repo.endpoint())?"":repo.endpoint());form.addView(endpoint,lp(-1,56));
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("高级连接设置").setView(form).setNegativeButton("取消",null).setPositiveButton("保存",null).create();
        dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{
            String value=endpoint.getText().toString().trim();try{
                if(!value.isEmpty()){java.net.URI uri=new java.net.URI(value);if((!"https".equals(uri.getScheme())&&!"http".equals(uri.getScheme()))||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null)throw new Exception("请输入有效的 HTTP 或 HTTPS 服务地址");}
                String selected=ApiEndpoint.selected(value);repo.auth.configure(selected,selected.equals(repo.endpoint())?repo.auth.authorization():"");VerificationBroker.instance().cancelAll("连接设置已变化，请重试");onAccountChanged();dialog.dismiss();render();toast("连接设置已保存");
            }catch(Exception error){endpoint.setError(error.getMessage()==null?"地址无效":error.getMessage());}
        }));dialog.show();
    }
    void onAccountChanged(){++cloudSerial;++cloudTrackSerial;++cloudOperation;cloudSyncing=false;cloudMutation=false;lastCloudResume=0;cloudMessage="";activeCloud=null;cloudFavoritesPage=false;if(page==7){page=2;tracks=new ArrayList<>();}++request;busy=false;if(service!=null&&service.current()!=null&&service.current().source.isEmpty())service.stopPlayback();syncCloud(true);}
    void saveLoginQr(android.graphics.Bitmap bitmap){pendingLoginQr=bitmap;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("image/png");intent.putExtra(Intent.EXTRA_TITLE,"EchoMusic-登录二维码.png");startActivityForResult(intent,11);}
    void importMusic(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("audio/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(intent,10);}
    @Override public void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==12){Song selected=pendingLyricImport;pendingLyricImport=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&selected!=null){Uri uri=data.getData();io.execute(()->{try(java.io.InputStream input=getContentResolver().openInputStream(uri);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream()){if(input==null)throw new java.io.IOException();byte[] buffer=new byte[4096];int count;while((count=input.read(buffer))!=-1){bytes.write(buffer,0,count);if(bytes.size()>2*1024*1024)throw new java.io.IOException("歌词文件过大");}String raw=Lyrics.decodeFile(bytes.toByteArray());if(raw.trim().isEmpty())throw new java.io.IOException("歌词内容为空");lyricsPanel.imported(selected,raw);}catch(Exception error){main.post(()->{if(!isDestroyed())toast("导入歌词失败："+error.getMessage());});}});}return;}if(req==11){android.graphics.Bitmap image=pendingLoginQr;pendingLoginQr=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&image!=null){try(java.io.OutputStream output=getContentResolver().openOutputStream(data.getData())){if(output==null||!image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,output))throw new java.io.IOException();toast("二维码已保存，请及时完成扫码确认");}catch(Exception error){toast("二维码保存失败，请重试");}}return;}if(req!=10||result!=RESULT_OK||data==null)return;List<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());List<Song> local=repo.saved("local");int count=0;for(Uri uri:uris){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}String name="本地音频";try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}catch(Exception ignored){}String key=uri.toString();if(local.stream().noneMatch(s->s.key().equals(key))){local.add(new Song(key,name,"本地音乐","","","",key));count++;}}repo.save("local",local);toast("已导入 "+count+" 首音乐");openSaved("local","本地音乐");}
    void play(List<Song> songs,int index){if(service==null){toast("播放器正在初始化");return;}startMusicService(new Intent(this,PlaybackService.class));service.play(new ArrayList<>(songs),index);updatePlayer();if(BuildConfig.TV)main.postDelayed(this::openPlayer,200);}
